/** One brand mark. Decorative by default: on this page every mark sits beside
 * the tool's name in text, so repeating the name to a screen reader is noise.
 * Pass `labelled` where the mark stands alone. */
export function BrandMark({
  id,
  className = "size-[13px]",
  labelled = false,
}: {
  id: BrandId
  className?: string
  labelled?: boolean
}) {
  const glyph = BRAND_MARKS[id]
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="currentColor"
      className={className}
      role={labelled ? "img" : undefined}
      aria-hidden={labelled ? undefined : "true"}
      aria-label={labelled ? glyph.title : undefined}
    >
      <path d={glyph.path} />
    </svg>
  )
}
